import { z } from 'zod';

import { listEventTypes } from './catalog';

/**
 * The text of docs/events.generated.md: every business event with when it fires, what it is
 * about, its data (JSON Schema) and an example. Generated by `pnpm actions:docs` so it cannot
 * drift from events/catalog.ts.
 */
export function eventsMarkdown(): string {
  const events = listEventTypes();
  const lines: string[] = [
    '<!-- GENERATED by `pnpm actions:docs` from packages/core/src/events/catalog.ts. Do not edit by hand. -->',
    '',
    '# Event catalog',
    '',
    'Every business event an action emits with `emit(tx, type, data)`. Automations are triggered by,',
    'wait for and are cancelled by these. See [events.md](./events.md) and [automations.md](./automations.md).',
    '',
    '| Event | About | When |',
    '| --- | --- | --- |',
    ...events.map(
      (e) =>
        `| [\`${e.type}\`](#${e.type.replace(/[._]/g, '')}) | ${e.subject?.type ?? ''} | ${firstSentence(e.description)} |`,
    ),
    '',
  ];
  for (const e of events) {
    lines.push(
      `### ${e.type}`,
      '',
      e.description,
      '',
      ...(e.subject ? [`- About: \`${e.subject.type}\``, ''] : []),
      '```json',
      JSON.stringify(z.toJSONSchema(e.data, { io: 'input', unrepresentable: 'any' }), null, 2),
      '```',
      '',
      'Example:',
      '',
      '```json',
      JSON.stringify(e.example, null, 2),
      '```',
      '',
    );
  }
  return lines.join('\n');
}

const firstSentence = (s: string) => {
  const m = /^(.+?[.!?])(\s|$)/.exec(s);
  return (m ? m[1]! : s).replace(/\|/g, '\\|');
};
